create or replace function hospitality.complete_housekeeping_inspection(p_task_id uuid,p_inspector uuid,p_result text,p_checklist jsonb default '[]'::jsonb,p_issues jsonb default '[]'::jsonb) returns uuid language plpgsql security definer set search_path=hospitality,vgroup,public as $$declare v_id uuid;begin if p_result not in('pass','fail') then raise exception 'invalid inspection result';end if;perform 1 from hospitality.housekeeping_tasks where id=p_task_id for update;if not found then raise exception 'housekeeping task not found';end if;insert into hospitality.housekeeping_inspections(task_id,inspector_id,result,checklist,issues) values(p_task_id,p_inspector,p_result,coalesce(p_checklist,'[]'::jsonb),coalesce(p_issues,'[]'::jsonb)) returning id into v_id;update hospitality.housekeeping_tasks set status=case when p_result='pass' then 'passed' else 'failed' end,completed_at=case when p_result='pass' then now() else completed_at end,updated_at=now() where id=p_task_id;return v_id;end$$;
create or replace function hospitality.calculate_dynamic_rate(p_property_id uuid,p_check_in date,p_check_out date,p_base_nightly numeric,p_occupancy numeric default 0) returns table(total_amount numeric,minimum_stay integer,applied_rules jsonb) language plpgsql stable set search_path=hospitality,public as $$declare v_nights int;v_total numeric;v_min int:=1;v_rules jsonb:='[]'::jsonb;r record;v_adjust numeric;begin if p_check_out<=p_check_in or p_base_nightly<0 or p_occupancy<0 or p_occupancy>100 then raise exception 'invalid stay/rate/occupancy';end if;v_nights:=p_check_out-p_check_in;v_total:=p_base_nightly*v_nights;for r in select * from hospitality.pricing_rules pr where pr.property_id=p_property_id and pr.active and(pr.starts_on is null or pr.starts_on<=p_check_out-1) and(pr.ends_on is null or pr.ends_on>=p_check_in) and(pr.occupancy_min is null or p_occupancy>=pr.occupancy_min) and(pr.occupancy_max is null or p_occupancy<=pr.occupancy_max) order by pr.priority,pr.created_at loop v_min:=greatest(v_min,r.minimum_stay);if r.rule_type<>'minimum_stay' then v_adjust:=case when r.adjustment_type='percent' then v_total*(r.adjustment_value/100) else r.adjustment_value*v_nights end;v_total:=greatest(0,v_total+v_adjust);end if;v_rules:=v_rules||jsonb_build_array(jsonb_build_object('id',r.id,'name',r.name,'type',r.rule_type,'value',r.adjustment_value));end loop;if v_nights<v_min then raise exception 'minimum stay is % nights',v_min;end if;return query select round(v_total,2),v_min,v_rules;end$$;
create or replace function hospitality.refresh_channel_reconciliation(p_id uuid) returns hospitality.channel_reconciliations language plpgsql security definer set search_path=hospitality,public as $$declare v hospitality.channel_reconciliations;begin update hospitality.channel_reconciliations set variance=round(actual_payout-(expected_payout-channel_fees),2),status=case when abs(actual_payout-(expected_payout-channel_fees))<=0.01 then 'matched' else 'variance' end,reconciled_at=now() where id=p_id returning * into v;if v.id is null then raise exception 'reconciliation not found';end if;return v;end$$;
create or replace function hospitality.procurement_match(p_purchase_order_id uuid,p_invoice_id uuid,p_goods_receipt_id uuid,p_actor uuid,p_tolerance numeric default 0.01) returns uuid language plpgsql security definer set search_path=hospitality,public as $$declare v_po numeric;v_inv numeric;v_bu uuid;v_id uuid;v_var numeric;begin select total,business_unit_id into v_po,v_bu from hospitality.purchase_orders where id=p_purchase_order_id;select total into v_inv from hospitality.invoices where id=p_invoice_id;if v_po is null or v_inv is null then raise exception 'PO or invoice missing';end if;if p_goods_receipt_id is not null and not exists(select 1 from hospitality.goods_receipts where id=p_goods_receipt_id and purchase_order_id=p_purchase_order_id and status in('partial','received')) then raise exception 'valid goods receipt required';end if;v_var:=round(v_inv-v_po,2);insert into hospitality.invoice_match_results(business_unit_id,purchase_order_id,invoice_id,goods_receipt_id,po_amount,invoice_amount,variance_amount,result,checked_by) values(v_bu,p_purchase_order_id,p_invoice_id,p_goods_receipt_id,v_po,v_inv,v_var,case when p_goods_receipt_id is null then 'blocked' when abs(v_var)<=p_tolerance then 'matched' else 'variance' end,p_actor) on conflict(purchase_order_id,invoice_id) do update set goods_receipt_id=excluded.goods_receipt_id,po_amount=excluded.po_amount,invoice_amount=excluded.invoice_amount,variance_amount=excluded.variance_amount,result=excluded.result,checked_by=excluded.checked_by,checked_at=now() returning id into v_id;return v_id;end$$;
create or replace function tech.capacity_forecast(p_business_unit_id uuid,p_horizon_days integer) returns table(user_id uuid,allocated_hours numeric,capacity_hours numeric,utilization_percent numeric) language sql stable set search_path=tech,public as $$select rc.user_id,coalesce(sum(rc.allocated_hours),0)::numeric,coalesce(sum(rc.capacity_hours),0)::numeric,case when coalesce(sum(rc.capacity_hours),0)=0 then 0 else round((sum(rc.allocated_hours)/sum(rc.capacity_hours))*100,2) end from tech.resource_capacity rc join tech.projects p on p.id=rc.project_id where p.business_unit_id=p_business_unit_id and rc.period_start<=current_date+p_horizon_days and rc.period_end>=current_date group by rc.user_id$$;
create or replace function tech.project_eac(p_project_id uuid) returns table(revenue numeric,cost_budget numeric,actual_cost numeric,etc numeric,eac numeric,forecast_margin_percent numeric) language sql stable set search_path=tech,public as $$with p as(select current_price,cost_budget,forecast_cost from tech.projects where id=p_project_id),c as(select coalesce(sum(amount),0)::numeric actual from tech.project_cost_entries where project_id=p_project_id) select p.current_price,p.cost_budget,c.actual,greatest(coalesce(nullif(p.forecast_cost,0),p.cost_budget)-c.actual,0),c.actual+greatest(coalesce(nullif(p.forecast_cost,0),p.cost_budget)-c.actual,0),case when p.current_price=0 then 0 else round(((p.current_price-(c.actual+greatest(coalesce(nullif(p.forecast_cost,0),p.cost_budget)-c.actual,0)))/p.current_price)*100,2) end from p,c$$;
create or replace function tech.approve_trial_extension(p_request_id uuid,p_actor uuid) returns timestamptz language plpgsql security definer set search_path=tech,public as $$declare v_until timestamptz;v_sub uuid;begin select requested_until,subscription_id into v_until,v_sub from tech.trial_extension_requests where id=p_request_id and status='pending' for update;if v_sub is null then raise exception 'pending trial extension not found';end if;update tech.trial_extension_requests set status='approved',decided_by=p_actor,decided_at=now() where id=p_request_id;update tech.subscriptions set trial_ends_at=greatest(coalesce(trial_ends_at,now()),v_until),updated_at=now() where id=v_sub;return v_until;end$$;

create or replace view vgroup.executive_command_center as select bu.id business_unit_id,bu.code,(select count(*) from vgroup.approval_requests ar where ar.business_unit_id=bu.id and ar.status='pending') pending_approvals,(select count(*) from vgroup.operational_exceptions oe where oe.business_unit_id=bu.id and oe.status in('open','investigating')) open_exceptions,case when bu.code='hospitality' then(select count(*) from hospitality.housekeeping_tasks ht where ht.business_unit_id=bu.id and ht.status not in('passed','cancelled')) else 0 end open_housekeeping,case when bu.code='hospitality' then(select count(*) from hospitality.guest_complaints gc where gc.business_unit_id=bu.id and gc.status not in('resolved','closed')) else 0 end open_guest_complaints,case when bu.code='tech' then(select count(*) from tech.support_tickets st where st.business_unit_id=bu.id and st.status not in('resolved','closed')) else 0 end open_support_tickets,case when bu.code='tech' then(select count(*) from tech.sales_opportunities so where so.business_unit_id=bu.id and so.stage not in('won','lost')) else 0 end open_sales_opportunities,(select coalesce(sum(case when l.direction='credit' then l.amount else -l.amount end),0) from vgroup.ledger_transactions l where l.business_unit_id=bu.id and date_trunc('month',l.occurred_at)=date_trunc('month',now())) month_net_movement from vgroup.business_units bu where bu.status='active';

DO $$declare t text;pol text;begin foreach t in array ARRAY['guests','guest_complaints','guest_conversations','guest_messages','housekeeping_tasks','housekeeping_inspections','pricing_rules','rate_quotes','stay_operations','guest_damage_claims','preventive_maintenance_plans','asset_warranties','vendor_scorecards','procurement_rfqs','procurement_vendor_quotes','goods_receipts','invoice_match_results','channel_reconciliations','tax_profiles','lost_found_items'] loop execute format('alter table hospitality.%I enable row level security',t);execute format('revoke all on hospitality.%I from anon, authenticated',t);execute format('grant all on hospitality.%I to service_role',t);pol:=t||'_server_only';if not exists(select 1 from pg_policies where schemaname='hospitality' and tablename=t and policyname=pol) then execute format('create policy %I on hospitality.%I for all to authenticated using(false) with check(false)',pol,t);end if;end loop;foreach t in array ARRAY['sales_leads','sales_opportunities','proposals','proposal_items','client_contracts','support_tickets','trial_extension_requests','delivery_handover_items','upsell_opportunities','scope_templates'] loop execute format('alter table tech.%I enable row level security',t);execute format('revoke all on tech.%I from anon, authenticated',t);execute format('grant all on tech.%I to service_role',t);pol:=t||'_server_only';if not exists(select 1 from pg_policies where schemaname='tech' and tablename=t and policyname=pol) then execute format('create policy %I on tech.%I for all to authenticated using(false) with check(false)',pol,t);end if;end loop;end$$;
revoke all on vgroup.executive_command_center from anon,authenticated;grant select on vgroup.executive_command_center to service_role;
revoke all on function hospitality.complete_housekeeping_inspection(uuid,uuid,text,jsonb,jsonb) from public,anon,authenticated;grant execute on function hospitality.complete_housekeeping_inspection(uuid,uuid,text,jsonb,jsonb) to service_role;
revoke all on function hospitality.calculate_dynamic_rate(uuid,date,date,numeric,numeric) from public,anon,authenticated;grant execute on function hospitality.calculate_dynamic_rate(uuid,date,date,numeric,numeric) to service_role;
revoke all on function hospitality.refresh_channel_reconciliation(uuid) from public,anon,authenticated;grant execute on function hospitality.refresh_channel_reconciliation(uuid) to service_role;
revoke all on function hospitality.procurement_match(uuid,uuid,uuid,uuid,numeric) from public,anon,authenticated;grant execute on function hospitality.procurement_match(uuid,uuid,uuid,uuid,numeric) to service_role;
revoke all on function tech.capacity_forecast(uuid,integer) from public,anon,authenticated;grant execute on function tech.capacity_forecast(uuid,integer) to service_role;
revoke all on function tech.project_eac(uuid) from public,anon,authenticated;grant execute on function tech.project_eac(uuid) to service_role;
revoke all on function tech.approve_trial_extension(uuid,uuid) from public,anon,authenticated;grant execute on function tech.approve_trial_extension(uuid,uuid) to service_role;

-- Cover every FK in the new operating tables without assuming generated index names.
DO $$declare r record;idx_name text;cols text;begin for r in select con.conrelid,n.nspname schema_name,cl.relname table_name,con.conname,con.conkey from pg_constraint con join pg_class cl on cl.oid=con.conrelid join pg_namespace n on n.oid=cl.relnamespace where con.contype='f' and((n.nspname='hospitality' and cl.relname in('guests','guest_complaints','guest_conversations','guest_messages','housekeeping_tasks','housekeeping_inspections','pricing_rules','rate_quotes','stay_operations','guest_damage_claims','preventive_maintenance_plans','asset_warranties','vendor_scorecards','procurement_rfqs','procurement_vendor_quotes','goods_receipts','invoice_match_results','channel_reconciliations','tax_profiles','lost_found_items'))or(n.nspname='tech' and cl.relname in('sales_leads','sales_opportunities','proposals','proposal_items','client_contracts','support_tickets','trial_extension_requests','delivery_handover_items','upsell_opportunities','scope_templates'))) and not exists(select 1 from pg_index i where i.indrelid=con.conrelid and i.indisvalid and(i.indkey::smallint[])[0:cardinality(con.conkey)-1]=con.conkey) loop select string_agg(quote_ident(a.attname),',' order by u.ord) into cols from unnest(r.conkey) with ordinality u(attnum,ord) join pg_attribute a on a.attrelid=r.conrelid and a.attnum=u.attnum;idx_name:=left('fkcov_'||r.table_name||'_'||replace(r.conname,r.table_name||'_',''),63);execute format('create index if not exists %I on %I.%I (%s)',idx_name,r.schema_name,r.table_name,cols);end loop;end$$;
